import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useParams } from "react-router-dom";
import private_api from "../../server/private_api";

const LecionaAvaliacao = () => {
  const { id } = useParams();
  const [cursos, setCursos] = useState([]);
  const [avaliacoes, setAvaliacoes] = useState([]);
  const [novaAvaliacao, setNovaAvaliacao] = useState({
    titulo: "",
    descricao: "",
    dataInicio: "",
    dataFim: "",
    pontuacaoMaxima: 20,
    cursoId: "",
  });

  useEffect(() => {
    // Carregar cursos do professor
    const fetchCursos = async () => {
      const resposta = await private_api.get(`/professores/${id}/listacursos`);
      if (resposta.status === 200) {
        setCursos(resposta.data);
      }
    };

    // Carregar avaliações criadas pelo professor
    const fetchAvaliacoes = async () => {
      const resposta = await private_api.get(`/professores/${id}/avaliacoes`);
      if (resposta.status === 200) {
        setAvaliacoes(resposta.data);
      }
    };

    fetchCursos();
    fetchAvaliacoes();
  }, [id]);

  const handleCriarAvaliacao = async () => {
    try {
      const resposta = await private_api.post("/avaliacoes", {
        ...novaAvaliacao,
        professorId: id,
      });
      if (resposta.status === 201) {
        alert("Avaliação criada com sucesso!");
        // Atualizar a lista de avaliações
        const avaliacoesResposta = await private_api.get(
          `/professores/${id}/avaliacoes`
        );
        setAvaliacoes(avaliacoesResposta.data);
      }
    } catch (error) {
      console.error("Erro ao criar avaliação:", error);
    }
  };

  return (
    <div
      className="container-fluid d-flex flex-column align-items-center"
      style={{
        backgroundColor: "#E7EFF4",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      <nav className="nav nav-tabs mb-3 bg-white p-2 w-75 d-flex justify-content-center">
        <a className="nav-link" href="#">
          Cursos
        </a>
        <a className="nav-link" href="#">
          Aulas
        </a>
        <a className="nav-link active" href="#">
          Avaliações
        </a>
      </nav>

      <h2 className="mb-3 text-center">Avaliações</h2>
      <div className="mb-3 w-75 d-flex justify-content-between">
        <div className="d-flex">
          <label className="me-2">Curso</label>
          <select
            className="me-3 form-select"
            style={{ width: "150px" }}
            value={novaAvaliacao.cursoId}
            onChange={(e) =>
              setNovaAvaliacao({ ...novaAvaliacao, cursoId: e.target.value })
            }
          >
            <option value="">Selecionar</option>
            {cursos.map((curso) => (
              <option key={curso.id} value={curso.id}>
                {curso.nome}
              </option>
            ))}
          </select>

          <label className="me-2">Pontuação Máxima</label>
          <input
            type="number"
            className="form-select"
            style={{ width: "80px" }}
            value={novaAvaliacao.pontuacaoMaxima}
            onChange={(e) =>
              setNovaAvaliacao({
                ...novaAvaliacao,
                pontuacaoMaxima: e.target.value,
              })
            }
          />
        </div>
        <button className="btn btn-primary" onClick={handleCriarAvaliacao}>
          Criar avaliação
        </button>
      </div>

      {/* Formulário para criar avaliação */}
      <div className="bg-white p-3 rounded shadow w-75 mb-4">
        <h4>Criar Nova Avaliação</h4>
        <div className="row mb-3">
          <div className="col-md-6">
            <label>Título</label>
            <input
              type="text"
              className="form-control"
              value={novaAvaliacao.titulo}
              onChange={(e) =>
                setNovaAvaliacao({ ...novaAvaliacao, titulo: e.target.value })
              }
            />
          </div>
          <div className="col-md-6">
            <label>Descrição</label>
            <input
              type="text"
              className="form-control"
              value={novaAvaliacao.descricao}
              onChange={(e) =>
                setNovaAvaliacao({
                  ...novaAvaliacao,
                  descricao: e.target.value,
                })
              }
            />
          </div>
        </div>
        <div className="row">
          <div className="col-md-6">
            <label>Data de Início</label>
            <input
              type="datetime-local"
              className="form-control"
              value={novaAvaliacao.dataInicio}
              onChange={(e) =>
                setNovaAvaliacao({
                  ...novaAvaliacao,
                  dataInicio: e.target.value,
                })
              }
            />
          </div>
          <div className="col-md-6">
            <label>Data de Fim</label>
            <input
              type="datetime-local"
              className="form-control"
              value={novaAvaliacao.dataFim}
              onChange={(e) =>
                setNovaAvaliacao({ ...novaAvaliacao, dataFim: e.target.value })
              }
            />
          </div>
        </div>
      </div>

      <div className="bg-white p-3 rounded shadow w-75">
        <h4>Avaliações enviadas</h4>
        <p>Os alunos concluíram as avaliações listadas abaixo.</p>
        <table className="table table-bordered mt-3">
          <thead>
            <tr>
              <th>Nome do Aluno</th>
              <th>ID do Aluno</th>
              <th>Título</th>
              <th>Pontuação registada</th>
              <th>Tempo</th>
              <th>Entregue</th>
            </tr>
          </thead>
          <tbody>
            {avaliacoes.length > 0 ? (
              avaliacoes.map((avaliacao, index) => (
                <tr key={index}>
                  <td>{avaliacao.nomeAluno}</td>
                  <td>{avaliacao.idAluno}</td>
                  <td>{avaliacao.titulo}</td>
                  <td>{avaliacao.pontuacao}</td>
                  <td>{avaliacao.tempo}</td>
                  <td>{avaliacao.entregue}</td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan="6" className="text-center">
                  Nenhuma avaliação submetida ainda
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default LecionaAvaliacao;
